# KEDA ScaledJob resources for SQS-driven task polling.
# Each job inherits ALL environment variables from the service to ensure env parity.
# Uses native Kubernetes provider since DuploCloud doesn't support ScaledJob CRD.
#
# NOTE: The CI/CD pipeline updates the container image via `kubectl patch` on every deploy
# (see the deploy workflows in each app repo). The container image is therefore treated as
# externally managed and listed in `ignore_fields` below, so `terraform apply` does NOT
# revert it to the bootstrap `service_image`. Reverting it would downgrade the SQS task
# workers to a stale build (this caused a screenshot/import-url incident in dev where the
# workers ran pre-fix code). `service_image` only seeds the image on first create.
#
# IMPORTANT: volumes/volumeMounts/envFrom here must stay in sync with
# Volumes/VolumesMounts/EnvFrom in duplocloud_duplo_service.job_secret_keeper above.
# No automated enforcement — if you add a CSI secret to one, add it to both.
resource "kubectl_manifest" "scaledjob" {
  for_each = var.jobs

  force_conflicts   = true
  server_side_apply = true

  # The container image is owned by the CI/CD pipeline (`kubectl patch`), not Terraform.
  # Ignoring it prevents `terraform apply` from reverting the workers to the stale
  # bootstrap `service_image`. See the NOTE above.
  ignore_fields = ["spec.jobTargetRef.template.spec.containers.0.image"]

  yaml_body = yamlencode({
    apiVersion = "keda.sh/v1alpha1"
    kind       = "ScaledJob"
    metadata = {
      name      = "${var.app_name}-${each.key}"
      namespace = "duploservices-${var.tenant_name}"
      labels = {
        app = var.app_name
        job = each.key
      }
    }

    spec = merge({
      jobTargetRef = {
        template = {
          metadata = {
            creationTimestamp = null
            labels = {
              app = var.app_name
              job = each.key
            }
          }

          spec = {
            restartPolicy      = "OnFailure"
            serviceAccountName = "duploservices-${var.tenant_name}-edit-user"
            nodeSelector = {
              tenantname = "duploservices-${var.tenant_name}"
            }

            containers = [
              {
                name    = "${var.app_name}-${each.key}"
                image   = var.service_image
                command = each.value.command

                env = [
                  for k, v in each.value.job_extra_env : {
                    name  = k
                    value = v
                  }
                ]

                envFrom = concat(
                  length(each.value.env_config) > 0 ? [
                    {
                      secretRef = {
                        name = duplocloud_k8_secret_provider_class.job_env_config[each.key].name
                      }
                    }
                  ] : [],
                  [
                    for key in keys(var.existing_config_params) : {
                      secretRef = {
                        name = duplocloud_k8_secret_provider_class.existing_config_params[key].name
                      }
                    }
                  ],
                  # Only when keys are declared; see local.env_secrets_enabled.
                  local.env_secrets_enabled ? [
                    {
                      secretRef = {
                        name = duplocloud_k8_secret_provider_class.env_secrets[0].name
                      }
                    }
                  ] : [],
                  [
                    {
                      secretRef = {
                        name = duplocloud_k8_secret_provider_class.env_config.name
                      }
                    }
                  ]
                )

                # Volume mounts for CSI secret store driver
                # These mount SSM parameters as files, which are then loaded as env vars via envFrom
                volumeMounts = concat(
                  # Job-specific config mount (if provided)
                  length(each.value.env_config) > 0 ? [
                    {
                      name      = "job-env-${each.key}"
                      mountPath = "/mnt/job-env-${each.key}"
                      readOnly  = true
                    }
                  ] : [],

                  # Existing config params mounts (redis, databases, etc.)
                  [
                    for key in keys(var.existing_config_params) : {
                      name      = key
                      mountPath = "/mnt/${key}"
                      readOnly  = true
                    }
                  ],

                  # Service config mount
                  [
                    {
                      name      = "env-config"
                      mountPath = "/mnt/env-config"
                      readOnly  = true
                    }
                  ],

                  # Service secrets mount (only when keys are declared)
                  local.env_secrets_enabled ? [
                    {
                      name      = "env-secrets"
                      mountPath = "/mnt/env-secrets"
                      readOnly  = true
                    }
