# WEV-4215: an apply that changes any other ScaledJob field server-side applies the
# whole manifest, so the manifest must carry the deployed image, not the bootstrap one.
run "existing_scaledjob_keeps_deployed_image" {
  command = apply
  override_data {
    target = data.kubernetes_resources.scaledjob_live["worker"]
    values = {
      objects = [{
        spec = {
          jobTargetRef = {
            template = {
              spec = {
                containers = [{ name = "test-service-worker", image = "example.invalid/test-service:deployed" }]
              }
            }
          }
        }
      }]
    }
  }
  assert {
    condition     = yamldecode(kubectl_manifest.scaledjob["worker"].yaml_body).spec.jobTargetRef.template.spec.containers[0].image == "example.invalid/test-service:deployed"
    error_message = "An existing ScaledJob must keep its deployed image on apply."
  }
}

run "new_scaledjob_uses_bootstrap_image" {
  command = apply
  override_data {
    target = data.kubernetes_resources.scaledjob_live["worker"]
