    condition     = yamldecode(kubectl_manifest.scaledjob["worker"].yaml_body).spec.jobTargetRef.template.spec.containers[0].image == "example.invalid/test-service:bootstrap"
    error_message = "A ScaledJob that does not exist yet must be created with service_image."
  }
}

