async function prepareRecoveryIntent({
  automatedInsightSessionId,
  attemptKind,
  rootAttemptKey,
  taskType,
  segmentId,
  manualRetry,
  suppliedAttemptKey,
  supersedesTaskId,
  errorPrefix,
  attemptKeyField,
}) {
  const latestIntent = await findLatestRecoveryIntentForRoot(rootAttemptKey);
  if (manualRetry) {
    const issuedIntent = await findIssuedRecoveryIntent({
      attemptKey: suppliedAttemptKey,
      rootAttemptKey,
      automatedInsightSessionId,
      attemptKind,
      taskType,
      segmentId,
    });
    if (!issuedIntent) {
      throw new WevoError({
        message: 'Manual recovery requires a server-issued token for this exact result state.',
        humanReadableMessage: 'Refresh the report before trying the manual recovery again.',
        status: HttpCodes.CONFLICT,
        error: `${errorPrefix}_manual_retry_intent_required`,
        details: {
          retryable: true,
          recoveryAction: 'refresh_report',
        },
      });
    }

    const currentIntent = latestIntent ?? issuedIntent;
    if (currentIntent.attemptKey !== issuedIntent.attemptKey) {
      if (
        currentIntent.state === RecoveryIntentState.Reserved ||
        (currentIntent.state === RecoveryIntentState.Launched && currentIntent.taskId)
      ) {
        return { intent: currentIntent, created: false };
      }
      throw new WevoError({
        message: 'The manual recovery token is no longer current for this result state.',
        humanReadableMessage: 'Refresh the report before trying the manual recovery again.',
        status: HttpCodes.CONFLICT,
        error: `${errorPrefix}_manual_retry_key_mismatch`,
        details: {
          [attemptKeyField]: currentIntent.attemptKey,
          retryable: true,
          recoveryAction: 'refresh_report',
        },
      });
    }

    if (
      currentIntent.state === RecoveryIntentState.Reserved &&
      isRecoveryIntentWithinReconciliationWindow(currentIntent)
    ) {
      return { intent: currentIntent, created: false };
    }
  } else if (latestIntent) {
    return { intent: latestIntent, created: false };
  }

  return persistRecoveryIntent({
    automatedInsightSessionId,
    attemptKind,
    attemptKey: issueRecoveryAttemptKey(rootAttemptKey),
    rootAttemptKey,
    requestMode: manualRetry ? RecoveryIntentMode.Manual : RecoveryIntentMode.Automatic,
    state: RecoveryIntentState.Reserved,
    taskId: null,
    supersedesTaskId: supersedesTaskId ?? null,
    segmentId: segmentId ?? null,
    taskType,
  });
}

function getRecoveryIntentTimestamp(intent) {
  const timestamp = new Date(intent?.createdAt ?? 0).getTime();
  return Number.isFinite(timestamp) && timestamp > 0 ? timestamp : null;
}

function isRecoveryIntentWithinReconciliationWindow(intent, now = Date.now()) {
  const createdAt = getRecoveryIntentTimestamp(intent);
  if (createdAt === null) {
    return false;
  }
  return now - createdAt <= RECOVERY_LAUNCH_RECONCILIATION_MS;
}

async function updateRecoveryIntent(intent, values) {
  if (!intent) {
    return null;
  }
  if (typeof intent.update === 'function') {
    return intent.update(values);
  }
  await models.AutomatedInsightRecoveryAttempt.update(values, { where: { id: intent.id } });
  Object.assign(intent, values);
  return intent;
}

async function markRecoveryIntentLaunched(intent, taskId) {
  return updateRecoveryIntent(intent, {
    state: RecoveryIntentState.Launched,
    taskId,
    launchedAt: new Date(),
    failedAt: null,
  });
}

